{"query":"query PullRequest($owner: String!, $repo: String!, $number: Int!) {
  viewer { login }
  repository(owner: $owner, name: $repo) {
    pullRequest(number: $number) { ...PullRequestFields }
  }
}

fragment ActorFields on Actor { __typename login }

fragment PageInfoFields on PageInfo { hasNextPage endCursor }

fragment ReviewRequestFields on ReviewRequest {
  id
  requestedReviewer {
    __typename
    ... on User { login }
    ... on Bot { login }
    ... on Mannequin { login }
    ... on Team { combinedSlug }
  }
}

fragment ReviewRequestsPage on ReviewRequestConnection {
  pageInfo { ...PageInfoFields }
  nodes { ...ReviewRequestFields }
}

fragment TimelineItemFields on PullRequestTimelineItems {
  __typename
  ... on PullRequestCommit {
    id
    commit { oid }
  }
  ... on PullRequestReview {
    id
    author { ...ActorFields }
    state
    body
    bodyText
    submittedAt
    url
    isMinimized
    commit { oid }
  }
  ... on IssueComment {
    id
    author { ...ActorFields }
    body
    bodyText
    createdAt
    url
    isMinimized
    minimizedReason
  }
  ... on HeadRefForcePushedEvent {
    id
    actor { ...ActorFields }
    createdAt
    beforeCommit { oid }
    afterCommit { oid }
  }
}

fragment TimelineItemsPage on PullRequestTimelineItemsConnection {
  pageInfo { ...PageInfoFields }
  nodes { ...TimelineItemFields }
}

fragment ReviewCommentFields on PullRequestReviewComment {
  id
  author { ...ActorFields }
  body
  bodyText
  createdAt
  url
  diffHunk
  path
  line
  originalLine
  outdated
  isMinimized
  commit { oid }
  originalCommit { oid }
  pullRequestReview { id }
  replyTo { id }
}

fragment ThreadCommentsPage on PullRequestReviewCommentConnection {
  pageInfo { ...PageInfoFields }
  nodes { ...ReviewCommentFields }
}

fragment ReviewThreadFields on PullRequestReviewThread {
  id
  path
  line
  startLine
  originalLine
  originalStartLine
  diffSide
  isResolved
  isOutdated
  isCollapsed
  resolvedBy { ...ActorFields }
  comments(first: 50) { ...ThreadCommentsPage }
}

fragment ReviewThreadsPage on PullRequestReviewThreadConnection {
  pageInfo { ...PageInfoFields }
  nodes { ...ReviewThreadFields }
}

fragment CheckRunFields on CheckRun {
  id
  name
  status
  conclusion
  startedAt
  completedAt
  detailsUrl
  url
  summary
  title
  isRequired(pullRequestNumber: $number)
}

fragment CheckRunsPage on CheckRunConnection {
  pageInfo { ...PageInfoFields }
  nodes { ...CheckRunFields }
}

fragment CheckSuiteFields on CheckSuite {
  id
  status
  conclusion
  createdAt
  updatedAt
  url
  app { slug name }
  push {
    id
    previousSha
    nextSha
    pusher { ...ActorFields }
  }
  workflowRun {
    id
    url
    workflow { name }
  }
  checkRuns(first: 50) { ...CheckRunsPage }
}

fragment CheckSuitesPage on CheckSuiteConnection {
  pageInfo { ...PageInfoFields }
  nodes { ...CheckSuiteFields }
}

fragment CommitFields on Commit {
  id
  oid
  abbreviatedOid
  messageHeadline
  committedDate
  authoredDate
  author {
    name
    user { ...ActorFields }
  }
  checkSuites(first: 10) { ...CheckSuitesPage }
}

fragment CommitsPage on PullRequestCommitConnection {
  pageInfo { ...PageInfoFields }
  nodes {
    id
    commit { ...CommitFields }
  }
}

fragment PullRequestFields on PullRequest {
  id
  number
  title
  url
  body
  bodyText
  state
  isDraft
  createdAt
  updatedAt
  closedAt
  mergedAt
  mergeable
  reviewDecision
  baseRefName
  headRefName
  headRefOid
  isCrossRepository
  viewerDidAuthor
  author { ...ActorFields }
  headRepository { nameWithOwner }
  viewerLatestReview {
    id
    state
    submittedAt
    commit { oid }
  }
  reviewRequests(first: 20) { ...ReviewRequestsPage }
  timelineItems(first: 100, itemTypes: [PULL_REQUEST_COMMIT, PULL_REQUEST_REVIEW, ISSUE_COMMENT, HEAD_REF_FORCE_PUSHED_EVENT]) { ...TimelineItemsPage }
  reviewThreads(first: 50) { ...ReviewThreadsPage }
  commits(first: 50) { ...CommitsPage }
}","variables":{"owner":"cli","repo":"cli","number":14429}}
